CREATE TABLE stores(
  store_id INT PRIMARY KEY,
  city VARCHAR(25) NOT NULL,
  district VARCHAR(25) NOT NULL,
  store_type VARCHAR(10) NOT NULL,
  opened_date DATE DEFAULT(CURRENT_DATE)
  ); --store table
